export async function getClaimInstructionAsync<
  TAccountConfig extends string,
  TAccountCampaign extends string,
  TAccountVault extends string,
  TAccountSubmission extends string,
  TAccountReport extends string,
  TAccountClipperTokenAccount extends string,
  TAccountMint extends string,
  TAccountClipper extends string,
  TAccountTokenProgram extends string,
  TProgramAddress extends Address = typeof VAULT_PROGRAM_ADDRESS,
>(
  input: ClaimAsyncInput<
    TAccountConfig,
    TAccountCampaign,
    TAccountVault,
    TAccountSubmission,
    TAccountReport,
    TAccountClipperTokenAccount,
    TAccountMint,
    TAccountClipper,
    TAccountTokenProgram
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  ClaimInstruction<
    TProgramAddress,
    TAccountConfig,
    TAccountCampaign,
    TAccountVault,
    TAccountSubmission,
    TAccountReport,
    TAccountClipperTokenAccount,
    TAccountMint,
    TAccountClipper,
    TAccountTokenProgram
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? VAULT_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    config: { value: input.config ?? null, isWritable: false },
    campaign: { value: input.campaign ?? null, isWritable: true },
    vault: { value: input.vault ?? null, isWritable: true },
    submission: { value: input.submission ?? null, isWritable: true },
    report: { value: input.report ?? null, isWritable: false },
    clipperTokenAccount: {
      value: input.clipperTokenAccount ?? null,
      isWritable: true,
    },
    mint: { value: input.mint ?? null, isWritable: false },
    clipper: { value: input.clipper ?? null, isWritable: true },
    tokenProgram: { value: input.tokenProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Resolve default values.
  if (!accounts.config.value) {
    accounts.config.value = await findConfigPda();
  }
  if (!accounts.vault.value) {
    accounts.vault.value = await findVaultPda({
      campaign: expectAddress(accounts.campaign.value),
    });
  }
  if (!accounts.report.value) {
    accounts.report.value = await findReportPda({
      submission: expectAddress(accounts.submission.value),
    });
  }
  if (!accounts.tokenProgram.value) {
    accounts.tokenProgram.value =
      "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA" as Address<"TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.config),
      getAccountMeta(accounts.campaign),
      getAccountMeta(accounts.vault),
      getAccountMeta(accounts.submission),
      getAccountMeta(accounts.report),
      getAccountMeta(accounts.clipperTokenAccount),
      getAccountMeta(accounts.mint),
      getAccountMeta(accounts.clipper),
      getAccountMeta(accounts.tokenProgram),
    ],
    data: getClaimInstructionDataEncoder().encode({}),
    programAddress,
  } as ClaimInstruction<
    TProgramAddress,
    TAccountConfig,
    TAccountCampaign,
    TAccountVault,
    TAccountSubmission,
    TAccountReport,
    TAccountClipperTokenAccount,
    TAccountMint,
    TAccountClipper,
    TAccountTokenProgram
  >);
}

